testcase.failure:
Resource: aws_s3_bucket.alb_logs
File: /alb.tf: 2-19
Guideline: https://docs.prismacloud.io/en/enterprise-edition/policy-reference/aws-policies/aws-general-policies/ensure-that-s3-buckets-are-encrypted-with-kms-by-default

		2  | resource "aws_s3_bucket" "alb_logs" {
		3  |   # Usamos un nombre único random para evitar conflictos
		4  |   bucket        = "alb-logs-${var.project_name}-${random_string.suffix.result}"
		5  |   force_destroy = true # Permite borrarlo aunque tenga datos (solo para lab)
		6  | 
		7  |   # CKV_AWS_18: Encriptar los logs para seguridad
		8  |   server_side_encryption_configuration {
		9  |     rule {
		10 |       apply_server_side_encryption_by_default {
		11 |         sse_algorithm = "AES256"
		12 |       }
		13 |     }
		14 |   }
		15 |   
		16 |   # CKV_AWS_144: No es necesario replicación cruzada para logs de lab
		17 |   # CKV_AWS_145: Usamos encriptación estándar AES256
		18 |   # CKV_AWS_21: Versionado no crítico para logs de lab
		19 | }

